class Translator:
    """Holds the current language and looks strings up by key. One instance per running application; the view
    keeps a reference and calls `set` when the user changes it in Settings."""

    def __init__(self, language: str = "en") -> None:
        self._language = language if language in LANGUAGES else "en"

    @property
    def language(self) -> str:
        return self._language

    def set(self, language: str) -> None:
        if language in LANGUAGES:
            self._language = language

    def __call__(self, key: str) -> str:
        entry = _STRINGS.get(key)
        if entry is None:
            return key
        return entry.get(self._language, entry["en"])
